import sys
from collections import Counter

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])
    numbers = [int(x) for x in input_data[1:]]

    if len(numbers) != n:
        pass

    if n < 3:
        print("NO")
        return

    freq = Counter(numbers)
    distinct_nums = sorted(freq.keys())

    if len(distinct_nums) > 2:
        for i in range(len(distinct_nums) - 1):
            if distinct_nums[i+1] - distinct_nums[i] > 1:
                print("NO")
                return
        if distinct_nums[-1] - distinct_nums[0] > 1:
            if distinct_nums[-1] - distinct_nums[0] != 1:
                print("NO")
                return
    elif len(distinct_nums) == 1:
        val = distinct_nums[0]
        if n >= 3:
            print("YES")
            return
        else:
            print("NO")
            return
    else:
        pass

    min_val = distinct_nums[0]
    max_val = distinct_nums[-1]

    if max_val - min_val > 1:
        print("NO")
        return

    if max_val - min_val == 0:
        if n >= 3:
            print("YES")
        else:
            print("NO")
        return

    count_min = freq[min_val]
    count_max = freq[max_val]

    if abs(count_min - count_max) > 1:
        print("NO")
        return

    print("YES")

if __name__ == "__main__":
    solve()
